package ru.replika.domain

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

/** Step 6 pure policy. The fixture is generated by tools/eval/tests/test_long_diar.py. */
class ChunkedDiarizationTest {
 private fun fixture(): JSONObject {
  val stream=checkNotNull(javaClass.classLoader!!.getResourceAsStream("step06/chunked-parity.json")) { "fixture missing" }
  return JSONObject(stream.bufferedReader(Charsets.UTF_8).use { it.readText() })
 }
 private fun JSONArray.longs()=LongArray(length()) { getLong(it) }
 private fun JSONArray.doubles()=DoubleArray(length()) { getDouble(it) }
 private fun turns(rows: JSONArray)=(0 until rows.length()).map { val r=rows.getJSONArray(it);Turn(r.getLong(0),r.getLong(1),r.getInt(2)) }
 private fun config(o: JSONObject)=ChunkedDiarization.Config(minDurationMs=o.getLong("min_duration_ms"),windowMs=o.getLong("window_ms"),
  overlapMs=o.getLong("overlap_ms"),globalTau=o.getDouble("global_tau"),maxSpeakers=o.getInt("max_speakers"),stitchSearchMs=o.getLong("stitch_search_ms"))

 @Test fun pythonParityFixtureMatchesEveryStepExactly() {
  val cases=fixture().getJSONArray("cases")
  assertTrue(cases.length()>=16)
  for(c in 0 until cases.length()) {
   val case=cases.getJSONObject(c);val cfg=config(case.getJSONObject("config"));val expected=case.getJSONObject("expected")
   val windows=ChunkedDiarization.planWindows(case.getLong("duration_ms"),cfg)
   val ew=expected.getJSONArray("windows")
   assertEquals("case $c windows",(0 until ew.length()).map { ew.getJSONArray(it).longs().toList() },windows.map { listOf(it.startMs,it.endMs) })
   val local=(0 until case.getJSONArray("local_turns").length()).map { turns(case.getJSONArray("local_turns").getJSONArray(it)) }
   val measured=case.getJSONArray("measured")
   val centroids=windows.indices.flatMap { k ->
    val rows=measured.getJSONArray(k)
    val items=(0 until rows.length()).map { val r=rows.getJSONArray(it)
     SpeakerRefiner.EmbeddingWindow(r.getLong(0),r.getLong(1),r.getInt(2),r.getJSONArray(3).doubles()) }
    ChunkedDiarization.windowCentroids(k,local[k],items)
   }
   val ec=expected.getJSONArray("centroids")
   assertEquals("case $c centroid count",ec.length(),centroids.size)
   for(i in centroids.indices) {
    val e=ec.getJSONArray(i)
    assertEquals(e.getInt(0),centroids[i].window);assertEquals(e.getInt(1),centroids[i].label);assertEquals(e.getLong(2),centroids[i].speechMs)
    val v=e.getJSONArray(3).doubles()
    assertArrayEquals("case $c centroid $i bits",v.map { it.toRawBits() }.toLongArray(),centroids[i].vector.map { it.toRawBits() }.toLongArray())
   }
   val labels=ChunkedDiarization.globalClusters(centroids,cfg)
   assertEquals("case $c labels",expected.getJSONArray("labels").let { a -> (0 until a.length()).map { a.getInt(it) } },labels.toList())
   val mapping=ChunkedDiarization.resolveLabels(local,centroids,labels)
   val em=expected.getJSONArray("mapping")
   for(k in windows.indices) {
    val rows=em.getJSONArray(k)
    assertEquals("case $c mapping $k",(0 until rows.length()).associate { rows.getJSONArray(it).getInt(0) to rows.getJSONArray(it).getInt(1) },mapping[k])
   }
   val cuts=ChunkedDiarization.stitchPoints(windows,local,cfg)
   assertEquals("case $c cuts",expected.getJSONArray("cuts").longs().toList(),cuts)
   assertEquals("case $c turns",turns(expected.getJSONArray("turns")),ChunkedDiarization.stitch(windows,local,mapping,cuts))
  }
 }

 @Test fun shortRecordingsNeverChunkAndEightHoursUseBoundedWindows() {
  val cfg=ChunkedDiarization.Config()
  assertFalse(ChunkedDiarization.isChunked(12*60_000L,cfg))
  assertEquals(listOf(ChunkedDiarization.Window(0,12*60_000L)),ChunkedDiarization.planWindows(12*60_000L,cfg))
  assertTrue(ChunkedDiarization.isChunked(12*60_000L+1,cfg))
  val eight=ChunkedDiarization.planWindows(8*3_600_000L,cfg)
  assertEquals(51,eight.size)
  assertEquals(0L,eight.first().startMs);assertEquals(8*3_600_000L,eight.last().endMs)
  assertTrue(eight.all { it.durationMs<=cfg.windowMs })
  for(k in 1 until eight.size) assertEquals(cfg.overlapMs,eight[k-1].endMs-eight[k].startMs)
 }

 @Test fun cannotLinkKeepsSimultaneousLabelsOfOneWindowApart() {
  val same=doubleArrayOf(1.0,0.0)
  val c=listOf(ChunkedDiarization.Centroid(0,0,same,1000),ChunkedDiarization.Centroid(0,1,same,1000),ChunkedDiarization.Centroid(1,0,same,1000))
  val labels=ChunkedDiarization.globalClusters(c,ChunkedDiarization.Config(globalTau=.5))
  assertNotEquals(labels[0],labels[1]);assertEquals(2,labels.distinct().size)
 }

 @Test fun invalidConfigurationsReject() {
  for(make in listOf({ ChunkedDiarization.Config(overlapMs=600_000L) },{ ChunkedDiarization.Config(minDurationMs=60_000L) },
   { ChunkedDiarization.Config(globalTau=1.0) })) {
   try { make();fail("invalid config") } catch(expected: IllegalArgumentException) { }
  }
 }
}
